  renderTree(){if(this.treeRename)return;this.validateTreeSelection();const el=$('#tree');el.replaceChildren();const render=(items,depth,hidden=false)=>{for(const f of items){const row=document.createElement('div');row.className='tree-row'+(hidden||f.name.startsWith('.')?' tree-hidden':'')+(this.treeSelection?.path===f.path?' selected':'');row.style.paddingLeft=7+depth*14+'px';row.title=relative(f.path,this.state.root);if(f.dir){if(f.unloaded)this.collapsed.add(f.path);row.innerHTML=`<span class="chevron">${svg(this.collapsed.has(f.path)?'chevron-right':'chevron-down')}</span>${svg('folder')}<span class="tree-label">${escapeHtml(f.name)}</span><span class="tree-file-menu" aria-label="Действия папки">${svg('ellipsis-vertical')}</span>`;row.oncontextmenu=e=>{e.preventDefault();this.folderMenu(f,e.clientX,e.clientY);};row.onclick=async e=>{this.selectTreeItem(f);if(e.target.closest('.tree-file-menu'))return this.folderMenu(f,e.clientX,e.clientY);if(f.unloaded){try{f.children=await native('tree',{path:f.path});f.unloaded=false;}catch(error){safeError(error);return;}}this.collapsed.has(f.path)?this.collapsed.delete(f.path):this.collapsed.add(f.path);this.renderTree();};}else{row.innerHTML=`<span class="chevron"></span><span class="file-icon">${fileSymbol(f.path)}</span><span class="tree-label">${escapeHtml(f.name)}</span><span class="tree-file-menu" aria-label="Действия файла">${svg('ellipsis-vertical')}</span>`;row.onclick=async e=>{this.selectTreeItem(f);if(e.target.closest('.tree-file-menu'))this.fileMenu(f,e.clientX,e.clientY);else this.openFile(f.path);};row.oncontextmenu=e=>{e.preventDefault();this.selectTreeItem(f);this.fileMenu(f,e.clientX,e.clientY);};}this.bindTreeRow(row,f);el.append(row);if(f.dir&&!this.collapsed.has(f.path))render(f.children,depth+1,hidden||f.name.startsWith('.'));}};render(this.treeData,0);this.updateTreeTarget();}
