      ['F5',()=>this.build(true)],['Shift+F5',()=>this.stop()],['F9',()=>this.build(false)],['Ctrl+W',()=>this.active&&this.closeTab(this.active)],['Ctrl+Tab',()=>this.cycleTab(1)],['Ctrl+Shift+Tab',()=>this.cycleTab(-1)]
