  cycleTab(direction){if(this.tabs.length)return this.openFile(this.tabs[(this.tabs.indexOf(this.active)+direction+this.tabs.length)%this.tabs.length].path);}
  menuItems(type){const c=label=>this.commands.find(c=>c.label===label);const groups={file:['Создать проект','Открыть папку устройства','Создать файл','Создать папку','Открыть файл',null,'Импортировать папку проекта','Импортировать файл','Экспортировать проект в ZIP',null,'Сохранить все файлы','Локальная история файла'],edit:['Поиск в файле','Заменить в файле','Перейти к строке',null,'Настройки'],code:['Отладка: собрать и запустить','Собрать','Собрать и запустить','Остановить',null,'Форматировать код','Настроить форматтер','Открыть .clang-format','Обновить CMake','Добавить файл в CMake',null,'Перейти к определению','Найти использования','Переименовать символ','Исправления и подсказки','Показать автодополнение','Показать документацию'],view:['Режим фокуса на коде','Развернуть/восстановить нижнюю панель',null,'Git: изменения',null,'Разделить редактор справа','Разделить редактор снизу','Один редактор',null,'Увеличить масштаб интерфейса','Уменьшить масштаб интерфейса','Сбросить расположение окон',null,'Показать ошибки','Показать консоль','Показать терминал','Скрыть/показать нижнюю панель','Скрыть/показать дерево проекта',null,'Перезапустить clangd','Инструменты','Диагностика отзывчивости','Справка и клавиши']};return groups[type].map(n=>n?c(n):null);}
  menu(items,x,y){StudioPopover.close();StudioChoices.close();const el=$('#menu');el.replaceChildren();for(const item of items){if(!item){el.append(document.createElement('hr'));continue;}const b=document.createElement('button');b.innerHTML=`${escapeHtml(tr(item.label))}${item.key?'<kbd>'+escapeHtml(item.key)+'</kbd>':''}`;b.onclick=()=>{el.classList.add('hidden');this.toggleMainMenu(false);Promise.resolve(item.run()).catch(safeError);};el.append(b);}el.classList.remove('hidden');el.style.left=Math.min(Math.max(4,x),innerWidth-el.offsetWidth-5)+'px';el.style.top=Math.min(y,innerHeight-el.offsetHeight-30)+'px';}
  quick(type){this.quickItems=type==='files'?this.flatFiles().map(f=>({label:f.name,noTranslate:true,detail:relative(f.path,this.state.root),run:()=>this.openFile(f.path)})):this.commands.map(c=>({...c,label:tr(c.label),detail:c.key}));this.openQuick(type==='files'?'Найти файл в проекте…':'Введите команду…');}
  openQuick(placeholder){$('#quickInput').value='';$('#quickInput').placeholder=placeholder;this.quickSelected=0;this.renderQuick();$('#quickDialog').showModal();$('#quickInput').focus();}
  renderQuick(reset=true){if(reset)this.quickSelected=0;const query=$('#quickInput').value.toLowerCase();this.filteredQuick=this.quickItems.filter(c=>(c.label+' '+(c.detail||'')).toLowerCase().includes(query)).slice(0,80);const el=$('#quickResults');el.replaceChildren();this.filteredQuick.forEach((item,i)=>{const b=document.createElement('button');b.className='quick-row'+(i===this.quickSelected?' active':'');b.innerHTML=`<span>${escapeHtml(item.noTranslate?item.label:tr(item.label))}</span><small>${escapeHtml(item.detail||'')}</small>`;b.onclick=()=>{this.quickSelected=i;this.executeQuick();};el.append(b);});if(!reset)el.children[this.quickSelected]?.scrollIntoView({block:'nearest'});}
  executeQuick(){const c=this.filteredQuick[this.quickSelected];if(!c)return;$('#quickDialog').close();Promise.resolve(c.run()).catch(safeError);}
  help(){$('#helpDialog').showModal();}
  toast(text){clearTimeout(this.toastTimer);$('#toast').textContent=tr(text);$('#toast').classList.remove('hidden');this.toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),5500);}
  back(){if(document.querySelector('#mainMenuToggle').getAttribute('aria-expanded')==='true'){this.toggleMainMenu(false);return;}if(document.body.classList.contains('panel-maximized')){this.maximizePanel(false);return;}if(StudioChoices.active){StudioChoices.close(true);return;}const d=$('dialog[open]');if(d){d.close();return;}if(document.body.classList.contains('sidebar-mobile-open')){document.body.classList.remove('sidebar-mobile-open');return;}if(!$('#menu').classList.contains('hidden')){$('#menu').classList.add('hidden');return;}if(this.editor.hasWidgetFocus()){this.editor.focus();this.editor.trigger('forge','closeFindWidget',null);}else this.toast('Проекты сохраняются автоматически. Для выхода используйте кнопку «Домой».');}
